313:   init() {
314:     const block = ['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' ','Enter','Escape'];
315:     window.addEventListener('keydown', (e) => {
316:       if (document.activeElement && document.activeElement.tagName === 'INPUT') return;
317:       if (block.includes(e.key)) e.preventDefault();
318:       const k = e.key.toLowerCase();
319:       if (!this.held[k]) {
320:         this.held[k] = true;
321:         this.pressHandlers.forEach(fn => fn(k, e));
322:       }
323:       if (e.key === 'Shift') this.held.shift = true;
324:     });
325:     window.addEventListener('keyup', (e) => {
326:       const k = e.key.toLowerCase();
327:       this.held[k] = false;
328:       if (e.key === 'Shift') this.held.shift = false;
329:     });
330:     window.addEventListener('blur', () => { this.held = {}; });
331:   },
332:   onPress(fn) { this.pressHandlers.push(fn); },
333:   down(...keys) { return keys.some(k => this.held[k]); },
334:   anyMove() { return this.down('arrowup','w') || this.down('arrowdown','s') || this.down('arrowleft','a') || this.down('arrowright','d'); }
335: };
