66: /* draw an outlined blob: silhouette + fill + shading + highlight */
67: function blob(c,cx,cy,rx,ry,dark,base,light,opts={}) {
68:   PX.ell(c,cx,cy,rx+2,ry+2,dark);
69:   PX.ell(c,cx,cy,rx,ry,base);
70:   PX.ell(c,cx-1,cy+ry*0.32,rx*0.78,ry*0.48,shiftColor(base,-8,.9,.82));
71:   if (opts.highlight!==false) PX.ell(c,cx-rx*0.25,cy-ry*0.34,rx*0.52,ry*0.3,light);
72:   // re-apply lower belly shading edge
73:   PX.ell(c,cx-rx*0.1,cy+ry*0.58,rx*0.66,ry*0.28,dark);
74:   PX.ell(c,cx-rx*0.05,cy+ry*0.5,rx*0.6,ry*0.3,shiftColor(base,-4,.85,.9));
75: }
76: 
77: function eye(c,x,y,rx,ry,opts={}) {
78:   PX.ell(c,x,y,rx+1,ry+1,'#1a1420');
79:   PX.ell(c,x,y,rx,ry,'#ffffff');
80:   PX.ell(c,x+ (opts.look||0.4)*rx*.4,y+ry*.05,rx*.62,ry*.66,opts.iris||'#1f2937');
81:   PX.ell(c,x-rx*.18,y-ry*.26,rx*.28,ry*.28,'#ffffff');
82:   if (opts.pupilShine!==false) PX.ell(c,x+rx*.25,y+ry*.2,rx*.12,ry*.14,'#ffffff');
83: }
