395: const CREATURE_CACHE = new Map();
396: function creatureCanvas(id, shiny = false, key = '') {
397:   const k = id + '|' + (shiny?'s':'n') + '|' + key;
398:   if (CREATURE_CACHE.has(k)) return CREATURE_CACHE.get(k);
399:   const sp = SPECIES[id];
400:   if (!sp) return null;
401:   const c = makeCreatureCanvas(sp, { shiny });
402:   CREATURE_CACHE.set(k, c);
403:   return c;
404: }
405: function drawCreature(ctx, id, x, y, size, opts = {}) {
406:   const sp = SPECIES[id];
407:   if (!sp) return;
408:   const c = creatureCanvas(id, opts.shiny || false, opts.cacheKey || '');
409:   if (!c) return;
410:   ctx.save();
411:   ctx.imageSmoothingEnabled = false;
412:   if (opts.flip) { ctx.translate(x + size/2, 0); ctx.scale(-1,1); ctx.translate(-(x + size/2),0); }
413:   if (opts.alpha != null) ctx.globalAlpha = opts.alpha;
414:   ctx.drawImage(c, x, y, size, size);
415:   ctx.restore();
416: }

